from numba import jit

@jit(nopython=True)
def limited_pd(q, qd, target, kp, kd, limit):
    tau = kp * (target - q) - kd * qd
    if tau > limit:
        return limit
    elif tau < -limit:
        return -limit
    return tau

@jit(nopython=True)
def smoothstep(u):
    u = min(max(u, 0.0), 1.0)
    return u * u * (3.0 - 2.0 * u)
